 static final String FINAL="kingdom_smp:librarian/j08";
 static void run(GameTestHelper h)throws Exception{
  var server=h.getLevel().getServer();var store=CommerceService.store(server);var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(h.getLevel(),id,"ThirdStudent");var player=p;var project=LibraryServiceRuntime.project(p);var b=BlueprintRegistry.get(project.blueprint(),1);var center=project.origin().offset(b.rotate(new BlockPos(7,1,6),project.rotation()));var proof=server.getWorldPath(LevelResource.ROOT).resolve("library-journey-final-test.nbt");
  if(Files.exists(proof)){h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().containsAll(java.util.stream.IntStream.rangeClosed(1,8).mapToObj(n->Profession.LIBRARIAN.questId(ProfessionRank.JOURNEYMAN,n)).toList())&&store.professions(id).track(Profession.LIBRARIAN).xp()==2400&&store.professions(id).progressBand(Profession.LIBRARIAN)==ProfessionRank.MASTER&&store.professions(id).rank(Profession.LIBRARIAN,ProfessionService.quests())==ProfessionRank.JOURNEYMAN,"All16earned2400XP and Master trials, not Master rank, restore after restart");h.assertTrue(store.serviceWork().customers(id,ServiceWorkState.LIBRARY)==2&&store.spentNativeOutputs(id,NativeOutputQuests.LIBRARY_FAMILIES)==4&&store.spentNativeOutputs(id,NativeOutputQuests.LIBRARY_MAXIMUM)==2&&h.getLevel().getEntity(project.npc())!=null,"Original consumed books/two current owners/Orin survive");CommerceService.verifyReceipt(p);h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(id).equals(store.professions(id)),"Matching canonical/native saved state reopens");com.mojang.logging.LogUtils.getLogger().info("LIBRARY_JOURNEY_RESTART_PASSED: all16actual native quests/2400XP/Master trials/original Orin/spent books/consent services/real magic catalogues/native visit and written guide/receipts restore");h.succeed();return;}
  h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().containsAll(Set.of(LibraryGlyphCatalogue.QUEST,LibrarySpellCatalogue.QUEST,ServiceWorkState.LIBRARY))&&com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(server).attainedTier()==6,"Cumulative actual research/consent source and existing Tier6 boundary required");books(h,p,project);if(store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().contains(LibraryFieldGuide.QUEST)){finish(h,p,center,proof);return;}var target=server.getLevel(ResourceKey.create(Registries.DIMENSION,ResourceLocation.parse("aether:the_aether")));h.assertTrue(target!=null&&LibraryExplorationService.supported("aether:the_aether"),"Exact real Aether dimension available");var destination=new BlockPos(0,250,0);target.getChunkAt(destination);var biome=target.getBiome(destination).unwrapKey().orElseThrow().location().toString();String text="My Aether field observations\ndimension=aether:the_aether biome="+biome+"\nFloating islands and native vegetation; personally inspected field notes.";var guide=LibraryFieldGuideRuntime.book(p,text);LibraryGlyphCatalogueRuntime.refuse(h,()->LibraryExplorationService.validate(player,guide));h.assertTrue(p.changeDimension(new DimensionTransition(target,Vec3.atCenterOf(destination),Vec3.ZERO,0,0,DimensionTransition.DO_NOTHING))==p,"Actual server-approved existing Tier6 travel enters native Aether without forced tier");for(int n=0;n<40;n++)p.doTick();h.runAfterDelay(2,()->{try{h.assertTrue(LibraryExplorationService.validate(player,guide).length()==64,"Actual native player/biome ticks produce bounded personal visit proof");h.assertTrue(player.changeDimension(new DimensionTransition(h.getLevel(),Vec3.atCenterOf(center),Vec3.ZERO,0,0,DimensionTransition.DO_NOTHING))==player,"Native Overworld return");LibraryFieldGuideRuntime.finish(h,player,project,center,text);finish(h,player,center,proof);}catch(Exception e){h.fail("Cumulative Library journey: "+e);}});
 }
 static void books(GameTestHelper h,ServerPlayer p,ConstructionStore.Project project)throws Exception{
  var b=BlueprintRegistry.get(project.blueprint(),1);BlockPos anvil=null;for(var pos:BlockPos.betweenClosed(project.origin(),project.origin().offset(b.width(project.rotation())-1,4,b.depth(project.rotation())-1)))if(p.serverLevel().getBlockState(pos).is(net.minecraft.tags.BlockTags.ANVIL)){anvil=pos.immutable();break;}h.assertTrue(anvil!=null,"Maintain original native Library bookbinding anvil");p.giveExperienceLevels(200);var noWear=new java.util.function.Consumer<net.neoforged.neoforge.event.entity.player.AnvilRepairEvent>(){public void accept(net.neoforged.neoforge.event.entity.player.AnvilRepairEvent e){if(e.getEntity()==p)e.setBreakChance(0);}};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(noWear);try{
   var store=CommerceService.store(p.server);long xp=store.professions(p.getUUID()).track(Profession.LIBRARIAN).xp();int missing=0;if(!store.professions(p.getUUID()).track(Profession.LIBRARIAN).completedQuestIds().contains(NativeOutputQuests.LIBRARY_MAXIMUM)){missing++;LibraryJourneymanRuntime.choose(p,project,NativeOutputQuests.LIBRARY_MAXIMUM);LibraryJourneymanRuntime.combine(h,p,anvil,"unbreaking",2,true);LibraryJourneymanRuntime.combine(h,p,anvil,"efficiency",4,true);LibraryServiceRuntime.counter(p);var q=ProfessionService.review(p,"enchanted:"+NativeOutputQuests.LIBRARY_MAXIMUM);ProfessionService.confirm(p,q.nonce());}if(!store.professions(p.getUUID()).track(Profession.LIBRARIAN).completedQuestIds().contains(NativeOutputQuests.LIBRARY_FAMILIES)){missing++;LibraryJourneymanRuntime.choose(p,project,NativeOutputQuests.LIBRARY_FAMILIES);for(var name:List.of("protection","efficiency","sharpness","unbreaking"))LibraryJourneymanRuntime.combine(h,p,anvil,name,1,true);LibraryServiceRuntime.counter(p);var q=ProfessionService.review(p,"enchanted:"+NativeOutputQuests.LIBRARY_FAMILIES);ProfessionService.confirm(p,q.nonce());}h.assertTrue(store.professions(p.getUUID()).track(Profession.LIBRARIAN).xp()==xp+200*missing&&store.spentNativeOutputs(p.getUUID(),NativeOutputQuests.LIBRARY_FAMILIES)==4&&store.spentNativeOutputs(p.getUUID(),NativeOutputQuests.LIBRARY_MAXIMUM)==2,"Actual full six native paid book combinations and permanent deliveries preserve all earlier service/research proofs");
  }finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(noWear);}
 }
 static void finish(GameTestHelper h,ServerPlayer p,BlockPos center,Path proof)throws Exception{
  var store=CommerceService.store(p.server);LibraryServiceRuntime.counter(p);if(!store.professions(p.getUUID()).track(Profession.LIBRARIAN).completedQuestIds().contains("kingdom_smp:librarian/j07")){var config=p.server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(p.server);var rules=com.google.gson.JsonParser.parseString(Files.readString(config)).getAsJsonObject();rules.getAsJsonObject("goals").addProperty("kingdom_smp:librarian/j07",1);Files.writeString(config,new com.google.gson.Gson().toJson(rules));CommissionQuestRules.clear(p.server);var terms=ContractRules.get(p.server).get("librarian/weekly");int left=terms.quantity();for(int i=0;i<36&&left>0;i++)if(p.getInventory().getItem(i).isEmpty()){int n=Math.min(64,left);p.getInventory().setItem(i,new ItemStack(terms.item(),n));left-=n;}h.assertTrue(left==0,"Full native weekly paper supply fits without replacing old equipment");int before=p.getInventory().countItem(terms.item());var delivery=ContractService.review(p,"librarian/weekly");ContractService.confirm(p,delivery.nonce());h.assertTrue(p.getInventory().countItem(terms.item())==before-terms.quantity(),"Actual complete weekly terms consume native paper and fund finite private coin mail");var q=ProfessionService.review(p,"quest:kingdom_smp:librarian/j07");ProfessionService.confirm(p,q.nonce());}
  var owner=ConstructionService.store(p.server).reward(ConstructionService.STARTING_HUT).orElseThrow().owner();var admin=p.server.getPlayerList().getPlayer(owner);if(admin==null)admin=ClaimRuntimeTests.vanillaPlayer(p.serverLevel(),owner,"LibraryInspector");p.server.getPlayerList().op(admin.getGameProfile());try{LibraryEnchantmentRuntime.inspect(admin,p,center,FINAL);}finally{p.server.getPlayerList().deop(admin.getGameProfile());}h.assertTrue(store.professions(p.getUUID()).track(Profession.LIBRARIAN).completedQuestIds().size()==16&&store.professions(p.getUUID()).track(Profession.LIBRARIAN).xp()==2400&&store.professions(p.getUUID()).progressBand(Profession.LIBRARIAN)==ProfessionRank.MASTER,"All16real native objectives now earn2400XP and open Master trials without fabricated prior progress");var saved=new CompoundTag();saved.putInt("schema",1);AtomicNbt.write(proof,saved);CommerceService.checkpoint(p);com.mojang.logging.LogUtils.getLogger().info("LIBRARY_JOURNEY_NATIVE_PASSED: cumulative original service and two real magic catalogues, six native book combinations/full XP-material costs/4family+2maximum permanent DEL, actual permitted Aether entry/native biome ticks/Overworld return/native readable guide+inspection, actual funded weekly paper delivery and current full Library final assessment/all16earned2400XP/Master trials; private weekly goal2to1/vanilla XP/raw inputs/anvil wear0 only, no tier/source/count/quest/professionXP/rank injection or default-duration/fullpack claim");h.succeed();
 }
